import { useState } from 'react';
import type { ArtifactRef, InteractionSnapshot, NavigationTarget, ProcessClient } from '@wright/process-client';
import {
  ProcessUI, Section, ProgressPanel, ResultCard, ReasonNotice, WorkingControls,
} from '@wright/ui-kit';
import './style.css';

export interface AppProps {
  client: ProcessClient;
  snapshot: InteractionSnapshot;
  readOnly: boolean;
}

const GEOMETRY = new Set([
  'define_geometry_basis_retained_consumer_001',
  'repair_measure_orient_retained_consumer_001',
]);
const SLICING = new Set([
  'supports_and_slice_retained_consumer_001',
  'retain_slice_response_retained_consumer_001',
]);
const INSPECTION = new Set([
  'inspect_slice_handoff_retained_consumer_001',
  'summarize_preparation_retained_consumer_001',
  'validate_outputs_retained_consumer_001',
  'authorize_transfer_retained_consumer_001',
]);

export default function App({ client, snapshot, readOnly }: AppProps) {
  const [navigationError, setNavigationError] = useState(false);
  const navigate = (target: NavigationTarget) => {
    setNavigationError(false);
    void client.navigate(target).catch(() => setNavigationError(true));
  };
  const openEvidence = (reference: ArtifactRef) => navigate({
    kind: 'evidence', artifact_ref: reference.artifact_ref, result_id: reference.result_id,
  });
  const outputs = snapshot.outputs ?? [];
  const blockOf = (output: unknown) => (output as { block_id?: string }).block_id;
  const groups = [
    { title: '1. Geometry basis and Blender repair', note: 'Review retained geometry-basis, source-mesh, repaired-mesh, orientation and preview results.', items: outputs.filter(o => GEOMETRY.has(blockOf(o) ?? '')) },
    { title: '2. External slicing handoff', note: 'Review the external slicing response and retained manufacturing package without treating provider success as compliance.', items: outputs.filter(o => SLICING.has(blockOf(o) ?? '')) },
    { title: '3. Retained inspection and transfer review', note: 'Review inspection evidence, profiles, preparation summaries, assessments and any authorization receipt.', items: outputs.filter(o => INSPECTION.has(blockOf(o) ?? '')) },
  ];
  const known = new Set([...GEOMETRY, ...SLICING, ...INSPECTION]);
  const other = outputs.filter(o => !known.has(blockOf(o) ?? ''));
  if (other.length) groups.push({ title: 'Other process results', note: 'Additional authoritative results reported by the current backend snapshot.', items: other });

  return <ProcessUI>
    <header className="hero">
      <div><p className="eyebrow">DIGITAL PREPARATION</p><h1>Focus-wheel preparation review</h1></div>
      <span className="scope">No physical-print controls</span>
    </header>
    <Section title="Preparation, progress and recovery">
      {readOnly && <p className="notice">Preview is read-only. Open the working presentation to prepare inputs or act on the process.</p>}
      <ProgressPanel state={snapshot.state} observations={snapshot.observations ?? []} />
      {(snapshot.diagnostics ?? []).map((reason, index) => <ReasonNotice key={`${reason.code}-${index}`} reason={reason} />)}
      {navigationError && <p role="alert" className="error">Wright could not open that exact target. Use the common working view to reconcile the current run and evidence.</p>}
      <WorkingControls client={client} snapshot={snapshot} readOnly={readOnly} onNavigate={navigate} />
    </Section>
    <div className="sequence" aria-label="Digital preparation result sequence">
      {groups.map(group => <Section key={group.title} title={group.title}>
        <p className="context">{group.note}</p>
        {group.items.length === 0
          ? <p className="empty">No results from this stage are present in the current snapshot.</p>
          : <div className="cards">{group.items.map(output => <ResultCard key={output.result_id} output={output} onNavigate={navigate} onOpen={openEvidence} />)}</div>}
      </Section>)}
    </div>
    <footer>Result cards preserve exact evidence and expose only supported representations. A preview, valid file, saved decision or successful provider response does not establish engineering acceptance.</footer>
  </ProcessUI>;
}

