.hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-4, 1rem);
  padding: var(--space-5, 1.25rem) 0 var(--space-3, .75rem);
  border-bottom: 1px solid var(--color-border, #d7dce2);
}
.hero h1 {
  margin: .15rem 0 0;
  font-size: clamp(1.45rem, 3vw, 2.15rem);
  line-height: 1.1;
}
.eyebrow {
  margin: 0;
  color: var(--color-text-muted, #59636e);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .14em;
}
.scope {
  padding: .35rem .6rem;
  border: 1px solid var(--color-border, #d7dce2);
  border-radius: 999px;
  color: var(--color-text-muted, #59636e);
  font-size: .76rem;
  white-space: nowrap;
}
.notice, .error {
  padding: .7rem .8rem;
  border-left: 3px solid var(--color-accent, #3859d6);
  background: var(--color-surface-subtle, #f4f6f8);
}
.error {
  border-left-color: var(--color-danger, #b42318);
}
.sequence {
  display: grid;
  gap: var(--space-4, 1rem);
}
.context, .empty, footer {
  color: var(--color-text-muted, #59636e);
}
.context {
  margin-top: 0;
}
.cards {
  display: grid;
  gap: var(--space-3, .75rem);
}
.empty {
  margin: .5rem 0;
  font-style: italic;
}
footer {
  margin-top: var(--space-5, 1.25rem);
  padding: var(--space-4, 1rem) 0;
  border-top: 1px solid var(--color-border, #d7dce2);
  font-size: .82rem;
  line-height: 1.5;
}
@media (max-width: 560px) {
  .hero { flex-direction: column; }
  .scope { white-space: normal; }
}
